FILTER_TERM = "Aster"


def _sheets(document: Any, title: str) -> list[Mapping[str, Any]]:
    if not isinstance(document, list):
        return []
    for book in document:
        if isinstance(book, Mapping) and str(book.get("title") or "") == title:
            return [sheet for sheet in (book.get("sheets") or []) if isinstance(sheet, Mapping)]
    return []


def _filter_present(document: Any, title: str, term: str) -> bool:
    wanted = term.strip().lower()
    for sheet in _sheets(document, title):
        filters = sheet.get("filters")
        if isinstance(filters, Mapping):
            active = filters.get("active")
            if isinstance(active, Mapping) and wanted in str(active.get("query") or "").lower():
                return True
        if wanted and wanted in json.dumps(filters, ensure_ascii=False).lower():
            return True
    return False


def _export_paths(params: Mapping[str, Any]) -> list[str]:
    declared = params.get("export_paths") or params.get("export_path")
    if isinstance(declared, str):
        declared = [declared]
    found: list[str] = []
    if isinstance(declared, (list, tuple)):
        for item in declared:
            text = str(item or "").strip()
            if text and text not in found:
                found.append(text)
    return found


def _export_files(controller: Any, patterns: list[str]) -> list[dict[str, Any]]:
    program = (
        "import glob, json, os\n"
        "patterns = json.loads(%s)\n"
        "found = []\n"
        "for pattern in patterns:\n"
        "    for path in sorted(glob.glob(pattern)):\n"
        "        try:\n"
        "            size = os.path.getsize(path)\n"
        "        except OSError:\n"
        "            size = 0\n"
        "        found.append({'path': path, 'size': size})\n"
        "print(json.dumps(found, ensure_ascii=False))\n"
    ) % json.dumps(json.dumps(patterns))
    parsed = _run_python(controller, program, timeout=60)
    if isinstance(parsed, list):
        return [dict(item) for item in parsed if isinstance(item, Mapping)]
    found: list[dict[str, Any]] = []
    for pattern in patterns:
        for path in sorted(glob.glob(pattern)):
            try:
                size = os.path.getsize(path)
            except OSError:
                size = 0
            found.append({"path": path, "size": size})
    return found


class OpenSheetAsterReviewEvaluator(OpenSheetPlantBudgetInventoryEvaluator):
    """Compare the stored OpenSheet workbook and export with the declared outcome."""

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = dict(context.get("params") or {})
        title = str(params.get("expected_workbook_title") or "quarterly-sales-aster-review")
        declared = dict(DECLARED)
        declared["expected_workbook_title"] = title

        inner = dict(context)
        inner["params"] = declared
        result = super().evaluate(inner)

        key = str(declared.get("state_key") or self.STATE_KEY)
        document, source = _read_document(context.get("controller"), key, _directories(declared))
        paths = _export_paths(params)
        files = _export_files(context.get("controller"), paths) if paths else []
        filtered = _filter_present(document, title, FILTER_TERM)

        metadata = dict(result.metadata or {})
        if source:
            metadata["source"] = source
        metadata["filter_term"] = FILTER_TERM
        metadata["filter_present"] = filtered
        metadata["export_paths"] = paths
        metadata["export_files"] = files
        result.metadata = metadata

        if result.status == EvalStatus.FAIL:
            return result

        failures: list[str] = []
        if not filtered:
            failures.append("filter")
        if paths and not files:
            failures.append("export")
        if failures:
            return EvalResult(
                status=EvalStatus.FAIL,
                message="the declared OpenSheet outcome is not present: %s"
                % ", ".join(failures),
                metadata=metadata,
            )
        return result
